// ─── Package catalog (packages.html) ────────────────────────────────────────
// Data source: assets/catalog.json, generated by scripts/build_ports.py.
(function () {
  "use strict";

  const URL_ = "assets/catalog.json";

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  }
  function fmtInt(n) { return Number(n || 0).toLocaleString("en-US"); }
  function fmtDate(iso) {
    const d = new Date(iso || "");
    return Number.isNaN(d.getTime()) ? "" : d.toISOString().slice(0, 10);
  }

  const CATEGORY_ORDER = ["core", "data", "port", "agent", "benchmark", "learn", "tools"];
  const LANG_LABEL = { python: "Python", rust: "Rust", other: "Other" };
  const PARITY = {
    pass: ["badge-pass", "parity pass"],
    partial: ["badge-partial", "parity partial"],
    gated: ["badge-gate", "parity gate"],
    unverified: ["badge-muted", "unverified"],
  };

  const state = { q: "", category: "all", domain: "all", lang: "all" };

  function searchText(p) {
    return [p.name, p.description, p.category, p.domain, p.lang, p.pypi, (p.upstream || {}).name, ...(p.topics || [])]
      .filter(Boolean).join(" ").toLowerCase();
  }

  function visible(p) {
    if (state.category !== "all" && p.category !== state.category) return false;
    if (state.domain !== "all" && p.domain !== state.domain) return false;
    if (state.lang !== "all" && p.lang !== state.lang) return false;
    return !state.q || p._search.includes(state.q);
  }

  function sortPackages(list) {
    const rank = (p) => CATEGORY_ORDER.indexOf(p.category);
    return list.slice().sort((a, b) => {
      if (rank(a) !== rank(b)) return rank(a) - rank(b);
      if ((b.stars || 0) !== (a.stars || 0)) return (b.stars || 0) - (a.stars || 0);
      return a.name.localeCompare(b.name);
    });
  }

  function monogram(name) {
    return esc(name.replace(/^(py|rust)-/i, "").slice(0, 2).toUpperCase());
  }

  function card(p, data) {
    const cats = data.categories || {};
    const doms = data.domains || {};
    const logo = p.logo_url
      ? `<span class="pkg-logo"><img src="${esc(p.logo_url)}" alt="" loading="lazy" data-repo-logo /><span class="pkg-mono" hidden>${monogram(p.name)}</span></span>`
      : `<span class="pkg-logo"><span class="pkg-mono">${monogram(p.name)}</span></span>`;
    const meta = [];
    if (p.version) meta.push(`<span class="pkg-version">${esc(p.version)}</span>`);
    if (p.license) meta.push(`<span>${esc(p.license)}</span>`);
    if (p.stars >= 5) meta.push(`<span>${fmtInt(p.stars)}★</span>`);
    const tags = [];
    if (p.domain && doms[p.domain]) tags.push(doms[p.domain]);
    else if (p.domain) tags.push(p.domain);
    if (p.category === "port" && p.upstream && p.upstream.source) tags.push(`from ${p.upstream.source}`);
    if (p.lang && p.category !== "port") tags.push(LANG_LABEL[p.lang] || p.lang);
    (p.topics || []).slice(0, 2).forEach((t) => { if (!tags.includes(t)) tags.push(t); });
    const links = [`<a href="${esc(p.html_url)}" target="_blank" rel="noopener">GitHub</a>`];
    if (p.docs) links.push(`<a href="${esc(p.docs)}" target="_blank" rel="noopener">Docs</a>`);
    if (p.pypi && p.lang !== "rust") links.push(`<a href="https://pypi.org/project/${esc(p.pypi)}/" target="_blank" rel="noopener">PyPI</a>`);
    if (p.catalog_url) links.push(`<a href="${esc(p.catalog_url)}">R ↔ Python map</a>`);
    if (p.upstream && p.upstream.url) links.push(`<a href="${esc(p.upstream.url)}" target="_blank" rel="noopener">Upstream</a>`);
    if (p.paper) links.push(`<a href="${esc(p.paper)}" target="_blank" rel="noopener">Paper</a>`);
    const parity = p.category === "port" && PARITY[p.parity_status]
      ? `<span class="badge ${PARITY[p.parity_status][0]}">${esc(PARITY[p.parity_status][1])}</span>` : "";
    return `<article class="pkg-card" data-name="${esc(p.name)}">
      <div class="pkg-head">
        ${logo}
        <div class="pkg-title">
          <a class="pkg-name" href="${esc(p.html_url)}" target="_blank" rel="noopener">${esc(p.name)}</a>
          <div class="pkg-meta"><span class="pkg-cat pkg-cat-${esc(p.category)}">${esc(cats[p.category] || p.category)}</span>${meta.map((m) => ` · ${m}`).join("")}</div>
        </div>
      </div>
      <p class="pkg-desc">${esc(p.description || "No description yet.")}</p>
      <div class="pkg-tags">${tags.map((t) => `<span class="pkg-tag">${esc(t)}</span>`).join("")}${parity}</div>
      <div class="pkg-links">${links.join("")}</div>
    </article>`;
  }

  function bindLogoFallbacks(root) {
    root.querySelectorAll("img[data-repo-logo]").forEach((img) => {
      img.addEventListener("error", () => {
        const mono = img.parentElement && img.parentElement.querySelector(".pkg-mono");
        img.remove();
        if (mono) mono.hidden = false;
      });
    });
  }

  function chips(holder, attr, items, allLabel, total) {
    holder.innerHTML = `<button class="chip-btn${state[attr] === "all" ? " active" : ""}" type="button" data-${attr}="all">${allLabel} <span class="chip-count">${total}</span></button>`
      + items.map(([key, label, n]) => `<button class="chip-btn${state[attr] === key ? " active" : ""}" type="button" data-${attr}="${esc(key)}">${esc(label)} <span class="chip-count">${n}</span></button>`).join("");
  }

  function renderChips(data) {
    const all = data.packages;
    const cats = data.categories || {};
    const doms = data.domains || {};
    const count = (key) => all.reduce((m, p) => { const k = p[key]; if (k) m[k] = (m[k] || 0) + 1; return m; }, {});
    const cc = count("category");
    chips(document.querySelector("[data-catalog-categories]"), "category",
      CATEGORY_ORDER.filter((k) => cc[k]).map((k) => [k, cats[k] || k, cc[k]]), "All", all.length);
    const dc = count("domain");
    const domainOrder = Object.keys(doms).concat(Object.keys(dc).filter((k) => !(k in doms)).sort());
    chips(document.querySelector("[data-catalog-domains]"), "domain",
      domainOrder.filter((k) => dc[k]).sort((a, b) => dc[b] - dc[a]).map((k) => [k, doms[k] || k, dc[k]]), "Any topic", all.length);
    const lc = count("lang");
    chips(document.querySelector("[data-catalog-langs]"), "lang",
      ["python", "rust", "other"].filter((k) => lc[k]).map((k) => [k, LANG_LABEL[k], lc[k]]), "Any language", all.length);
  }

  function render(data) {
    const grid = document.querySelector("[data-catalog-grid]");
    const list = sortPackages(data.packages.filter(visible));
    grid.innerHTML = list.map((p) => card(p, data)).join("");
    bindLogoFallbacks(grid);
    document.querySelector("[data-catalog-empty]").hidden = list.length > 0;
    document.querySelector("[data-catalog-count]").textContent = `${list.length} of ${data.packages.length} packages`;
    renderChips(data);
  }

  function bind(data) {
    const search = document.querySelector("[data-catalog-search]");
    let t = null;
    search.addEventListener("input", () => {
      window.clearTimeout(t);
      t = window.setTimeout(() => { state.q = search.value.trim().toLowerCase(); render(data); }, 80);
    });
    document.addEventListener("click", (ev) => {
      const b = ev.target.closest(".chip-btn");
      if (!b) return;
      for (const key of ["category", "domain", "lang"]) {
        if (b.dataset[key] != null) { state[key] = b.dataset[key]; render(data); return; }
      }
    });
  }

  async function init() {
    if (!document.querySelector("[data-catalog-root]")) return;
    let data;
    try {
      const res = await fetch(URL_, { cache: "no-cache" });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      data = await res.json();
    } catch (err) {
      document.querySelector("[data-catalog-grid]").innerHTML = `<p class="fetch-error">Couldn't load the package catalog. <a href="https://github.com/omicverse" target="_blank" rel="noopener">View the org on GitHub →</a></p>`;
      return;
    }
    data.packages = (data.packages || []).map((p) => ({ ...p, _search: searchText(p) }));
    const foot = document.querySelector("[data-catalog-footnote]");
    if (foot && data.generated_at) foot.insertAdjacentHTML("beforeend", ` Last generated ${esc(fmtDate(data.generated_at))}.`);
    const q = new URLSearchParams(location.search);
    if (q.get("category")) state.category = q.get("category");
    if (q.get("topic")) state.domain = q.get("topic");
    bind(data);
    render(data);
  }

  init();
})();
